package com.universalplatform.content;
import java.nio.file.*; import java.time.*; import java.util.List; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component class UploadCleanupWorker {private final UploadSessionRepository uploads;private final Clock clock=Clock.systemUTC();UploadCleanupWorker(UploadSessionRepository uploads){this.uploads=uploads;}@Scheduled(fixedDelayString="${platform.storage.upload-cleanup-poll-ms:3600000}")@Transactional void expire(){for(UploadSession u:uploads.findTop100ByStatusInAndExpiresAtBeforeOrderByExpiresAtAsc(List.of(UploadStatus.INITIATED,UploadStatus.UPLOADING,UploadStatus.VERIFYING),clock.instant())){u.status=UploadStatus.EXPIRED;try{Files.deleteIfExists(Path.of(u.stagingPath));}catch(Exception ignored){}}}}
